/**
 * tube-map-data.ts -- Schematic tube map station positions and line routes
 *
 * Contains pre-defined x,y coordinates for every station on the
 * London Underground, DLR, and Elizabeth line network.
 *
 * Coordinates are in a 1200x800 virtual canvas space.
 * The layout approximates the classic Harry Beck tube map style
 * with stations plotted based on their relative geographic positions.
 *
 * This file is auto-generated from TfL API data with positions
 * normalized to the canvas space. Further manual adjustment can
 * refine the schematic layout.
 */

/* ========================================
 * TYPES
 * ======================================== */

/** A station's position on the schematic map */
export interface SchematicStation {
  /** TfL Naptan ID (e.g. "940GZZLUVIC") */
  naptanId: string;
  /** Clean display name (e.g. "Victoria") */
  name: string;
  /** X position on the schematic (0-1200) */
  x: number;
  /** Y position on the schematic (0-800) */
  y: number;
  /** Which lines serve this station */
  lines: string[];
  /** Label placement hint */
  labelPosition?: "left" | "right" | "above" | "below";
}

/** A line's route through the schematic */
export interface SchematicLine {
  /** TfL line ID (e.g. "central") */
  lineId: string;
  /** Ordered arrays of station IDs forming each branch */
  branches: string[][];
}

