/* ========================================
 * HELPER: Build a station lookup map
 * ======================================== */

/** Quick lookup: naptanId -> station data */
export function buildStationMap(): Map<string, SchematicStation> {
  const map = new Map<string, SchematicStation>();
  for (const station of STATIONS) {
    map.set(station.naptanId, station);
  }
  return map;
}

/** Quick lookup: station name -> station data (for train tracking) */
export function buildNameLookup(): Map<string, { x: number; y: number; naptanId: string }> {
  const map = new Map<string, { x: number; y: number; naptanId: string }>();
  for (const station of STATIONS) {
    map.set(station.name, { x: station.x, y: station.y, naptanId: station.naptanId });
  }
  return map;
}
